 * rejects anything else. Use it in the contract test:
 *
 *   const { fetch, calls } = contractFetch()
 *   await handle(SOURCE_EXAMPLE as MyInput, { ...config, fetch })
 *   expect(calls.length).toBeGreaterThan(0)
 */
export function contractFetch(): { fetch: typeof fetch; calls: RecordedCall[] } {
  return fakeFetch((request) => {
    const endpoint = findEndpoint(request.method, request.url)
    if (!endpoint) throw new Error(`contract: ${request.method} ${request.url} is not a documented endpoint`)
    return jsonResponse(endpoint.response)
  })
}

/**
 * A correctly typed fake fetch for every other test. The handler receives the recorded
 * request: { method, url, body (string as sent), json (parsed body), headers (Headers) }.
 *
 *   const { fetch, calls } = fakeFetch((req) => req.url.endsWith('/deals') ? jsonResponse({ id: 1 }, 201) : jsonResponse({}, 404))
 */
export function fakeFetch(
  handler: (request: RecordedCall) => Response | Promise<Response>,
): { fetch: typeof fetch; calls: RecordedCall[] } {
  const calls: RecordedCall[] = []
  const fake = async (input: string | URL | Request, init: RequestInit = {}): Promise<Response> => {
    const url = input instanceof Request ? input.url : String(input)
    const method = (init.method ?? (input instanceof Request ? input.method : 'GET')).toUpperCase()
    const body = typeof init.body === 'string' ? init.body : init.body == null ? undefined : String(init.body)
    const call: RecordedCall = { method, url, body, json: parseJson(body), headers: new Headers(init.headers) }
    calls.push(call)
    return handler(call)
  }
  return { fetch: fake as typeof fetch, calls }
}

const STATUS_TEXT: Record<number, string> = {
  200: 'OK', 201: 'Created', 202: 'Accepted', 204: 'No Content',
  400: 'Bad Request', 401: 'Unauthorized', 403: 'Forbidden', 404: 'Not Found', 409: 'Conflict',
  422: 'Unprocessable Entity', 429: 'Too Many Requests',
  500: 'Internal Server Error', 502: 'Bad Gateway', 503: 'Service Unavailable',
}

/** A JSON Response with the standard status text, e.g. jsonResponse({ error: 'nope' }, 401) -> "401 Unauthorized". */
export function jsonResponse(body: unknown, status = 200): Response {
  const init = { status, statusText: STATUS_TEXT[status] ?? '', headers: { 'Content-Type': 'application/json' } }
  return new Response(status === 204 ? null : JSON.stringify(body), init)
}

function parseJson(raw: string | undefined): unknown {
  if (raw === undefined) return undefined
  try {
    return JSON.parse(raw)
  } catch {
    return undefined
  }
}

function urlMatches(template: string, actual: string): boolean {
  const t = splitUrl(template)
  const a = splitUrl(actual)
  if (!t || !a) return false
  const tHost = t.host.split('.')
  const aHost = a.host.split('.')
  if (tHost.slice(-2).join('.') !== aHost.slice(-2).join('.')) return false
  const tPath = t.path.replace(/\/+$/, '').split('/')
  const aPath = a.path.replace(/\/+$/, '').split('/')
  if (tPath.length !== aPath.length) return false
  return tPath.every((segment, i) => isPlaceholder(segment) || segment === aPath[i])
}

function splitUrl(url: string): { host: string; path: string } | null {
  const match = url.match(/^https?:\/\/([^/?#]+)([^?#]*)/i)
  return match ? { host: (match[1] ?? '').toLowerCase(), path: match[2] || '/' } : null
}

function isPlaceholder(segment: string): boolean {
  return /^\{[^}]+\}$|^:[A-Za-z_]\w*$|^<[^>]+>$/.test(segment)
}

export interface ConnectorConfig {
  asanaAccessToken: string
  asanaWorkspaceGid: string
  fetch?: typeof fetch
}

export interface JotformSubmissionPayload {
  answers: Record<string, string>
  submissionID: string
  formID: string
}

export interface AsanaTaskResult {
  taskGid: string
  taskName: string
}

function getFetch(config: ConnectorConfig): typeof fetch {
  return config.fetch ?? fetch
}

function validatePayload(payload: unknown): asserts payload is JotformSubmissionPayload {
  if (!payload || typeof payload !== 'object') {
    throw new Error('Payload must be an object')
  }
  const p = payload as Record<string, unknown>
  if (!p.answers || typeof p.answers !== 'object') {
    throw new Error('Missing required field: answers')
  }
  if (!p.submissionID || typeof p.submissionID !== 'string') {
    throw new Error('Missing required field: submissionID')
  }
  if (!p.formID || typeof p.formID !== 'string') {
    throw new Error('Missing required field: formID')
  }
}

function buildTaskName(answers: Record<string, string>): string {
  const first = answers.first_name ?? ''
  const last = answers.last_name ?? ''
  const name = [first, last].filter(Boolean).join(' ')
  return name || 'Jotform Submission'
}

function buildTaskNotes(answers: Record<string, string>): string {
  const lines: string[] = []
  if (answers.email) lines.push(`Email: ${answers.email}`)
  if (answers.phone) lines.push(`Phone: ${answers.phone}`)
  if (answers.company) lines.push(`Company: ${answers.company}`)

  const otherAnswers = Object.entries(answers).filter(
    ([key]) => !['first_name', 'last_name', 'email', 'phone', 'company'].includes(key)
  )
  if (otherAnswers.length > 0) {
    const answersStr = otherAnswers.map(([k, v]) => `${k}=${v}`).join(', ')
    lines.push(`Answers: ${answersStr}`)
  }

  return lines.join('\n')
}

export async function handle(
  payload: JotformSubmissionPayload,
  config: ConnectorConfig
): Promise<AsanaTaskResult> {
  validatePayload(payload)

  const fetchFn = getFetch(config)
  const taskName = buildTaskName(payload.answers)
  const taskNotes = buildTaskNotes(payload.answers)

  const requestBody = {
    data: {
      name: taskName,
      notes: taskNotes,
      workspace: config.asanaWorkspaceGid,
    },
  }

  const response = await fetchFn('https://app.asana.com/api/1.0/tasks', {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${config.asanaAccessToken}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(requestBody),
  })

  if (!response.ok) {
    throw new Error(`Asana API error: ${response.status} ${response.statusText} at POST https://app.asana.com/api/1.0/tasks`)
  }

  const data = (await response.json()) as { data: { gid: string; name: string } }
  return {
    taskGid: data.data.gid,
    taskName: data.data.name,
  }
}

import { describe, it, expect, vi } from 'vitest'
import { handle, ConnectorConfig, JotformSubmissionPayload } from './connector'
import {
  SOURCE_EXAMPLE,
  TARGET_ENDPOINTS,
  contractFetch,
  fakeFetch,
  jsonResponse,
  type RecordedCall,
} from './fixtures'

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch()
    const config: ConnectorConfig = {
      asanaAccessToken: 'test-token',
      asanaWorkspaceGid: '1234567890123',
      fetch,
    }
    const result = await handle(SOURCE_EXAMPLE as unknown as JotformSubmissionPayload, config)
    expect(calls.length).toBeGreaterThan(0)
    expect(result.taskGid).toBe('9876543210')
    expect(result.taskName).toBe('John Doe')
  })
})

describe('handle', () => {
  it('creates an Asana task with correct field mapping on happy path', async () => {
    const { fetch, calls } = fakeFetch((req: RecordedCall) => {
      if (req.url === 'https://app.asana.com/api/1.0/tasks' && req.method === 'POST') {
        return jsonResponse({
          data: {
            gid: '9876543210',
            name: 'John Doe',
            notes: 'Email: john.doe@example.com\nPhone: 555-1234\nCompany: Acme Corp\nAnswers: field_123=Answer to question 1, field_456=Answer to question 2',
            workspace: { gid: '1234567890123', resource_type: 'workspace', name: 'Company Workspace' },
          },
        }, 201)
      }
      return jsonResponse({ error: 'not found' }, 404)
    })

    const config: ConnectorConfig = {
      asanaAccessToken: 'test-token',
      asanaWorkspaceGid: '1234567890123',
      fetch,
    }

    const payload: JotformSubmissionPayload = {
      answers: {
        first_name: 'John',
        last_name: 'Doe',
        email: 'john.doe@example.com',
        phone: '555-1234',
        company: 'Acme Corp',
        field_123: 'Answer to question 1',
        field_456: 'Answer to question 2',
      },
      submissionID: '1234567890',
      formID: '987654321',
    }

    const result = await handle(payload, config)

    expect(result.taskGid).toBe('9876543210')
    expect(result.taskName).toBe('John Doe')
    expect(calls).toHaveLength(1)

    const call = calls[0]
    expect(call.method).toBe('POST')
    expect(call.url).toBe('https://app.asana.com/api/1.0/tasks')
    expect(call.headers.get('authorization')).toBe('Bearer test-token')
    expect(call.headers.get('content-type')).toBe('application/json')

    const sentBody = call.json as { data: { name: string; notes: string; workspace: string } }
    expect(sentBody.data.name).toBe('John Doe')
    expect(sentBody.data.workspace).toBe('1234567890123')
    expect(sentBody.data.notes).toContain('Email: john.doe@example.com')
    expect(sentBody.data.notes).toContain('Phone: 555-1234')
    expect(sentBody.data.notes).toContain('Company: Acme Corp')
    expect(sentBody.data.notes).toContain('field_123=Answer to question 1')
    expect(sentBody.data.notes).toContain('field_456=Answer to question 2')
  })

  it('uses Bearer token authentication', async () => {
    const { fetch, calls } = fakeFetch((req: RecordedCall) => {
      if (req.url === 'https://app.asana.com/api/1.0/tasks' && req.method === 'POST') {
        const auth = req.headers.get('authorization')
        if (auth === 'Bearer secret-token-123') {
          return jsonResponse({ data: { gid: '111', name: 'Test' } }, 201)
        }
        return jsonResponse({ error: 'unauthorized' }, 401)
      }
      return jsonResponse({ error: 'not found' }, 404)
    })

    const config: ConnectorConfig = {
      asanaAccessToken: 'secret-token-123',
      asanaWorkspaceGid: '999',
      fetch,
    }

    const payload: JotformSubmissionPayload = {
      answers: { first_name: 'Test', last_name: 'User' },
      submissionID: 'sub-1',
      formID: 'form-1',
    }

    await handle(payload, config)
    expect(calls[0].headers.get('authorization')).toBe('Bearer secret-token-123')
  })

  it('maps all form answers into task description', async () => {
    const { fetch, calls } = fakeFetch((req: RecordedCall) => {
      if (req.url === 'https://app.asana.com/api/1.0/tasks' && req.method === 'POST') {
        return jsonResponse({ data: { gid: '222', name: 'Test' } }, 201)
      }
      return jsonResponse({ error: 'not found' }, 404)
    })

    const config: ConnectorConfig = {
      asanaAccessToken: 'token',
      asanaWorkspaceGid: 'ws-1',
      fetch,
    }

    const payload: JotformSubmissionPayload = {
      answers: {
        first_name: 'Jane',
        last_name: 'Smith',
        email: 'jane@test.com',
        phone: '555-0000',
        company: 'Test Inc',
        custom_field_a: 'Custom answer A',
        custom_field_b: 'Custom answer B',
        custom_field_c: 'Custom answer C',
      },
      submissionID: 'sub-2',
      formID: 'form-2',
    }

    await handle(payload, config)

    const sentBody = calls[0].json as { data: { notes: string } }
    expect(sentBody.data.notes).toContain('custom_field_a=Custom answer A')
    expect(sentBody.data.notes).toContain('custom_field_b=Custom answer B')
    expect(sentBody.data.notes).toContain('custom_field_c=Custom answer C')
  })

  it('throws descriptive error when answers field is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const config: ConnectorConfig = { asanaAccessToken: 't', asanaWorkspaceGid: 'w', fetch }

    const payload = { submissionID: '1', formID: '2' } as unknown as JotformSubmissionPayload

    await expect(handle(payload, config)).rejects.toThrow('Missing required field: answers')
  })

  it('throws descriptive error when submissionID is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const config: ConnectorConfig = { asanaAccessToken: 't', asanaWorkspaceGid: 'w', fetch }

    const payload = { answers: {}, formID: '2' } as unknown as JotformSubmissionPayload

    await expect(handle(payload, config)).rejects.toThrow('Missing required field: submissionID')
  })

  it('throws descriptive error when formID is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const config: ConnectorConfig = { asanaAccessToken: 't', asanaWorkspaceGid: 'w', fetch }

    const payload = { answers: {}, submissionID: '1' } as unknown as JotformSubmissionPayload

    await expect(handle(payload, config)).rejects.toThrow('Missing required field: formID')
  })

  it('throws error with status and endpoint on non-2xx response', async () => {
    const { fetch, calls } = fakeFetch((req: RecordedCall) => {
      if (req.url === 'https://app.asana.com/api/1.0/tasks' && req.method === 'POST') {
        return jsonResponse({ errors: [{ message: 'Invalid token' }] }, 401)
      }
      return jsonResponse({ error: 'not found' }, 404)
    })

    const config: ConnectorConfig = {
      asanaAccessToken: 'bad-token',
      asanaWorkspaceGid: 'ws-1',
      fetch,
    }

    const payload: JotformSubmissionPayload = {
      answers: { first_name: 'Test' },
      submissionID: 'sub-1',
      formID: 'form-1',
    }

    await expect(handle(payload, config)).rejects.toThrow(
      'Asana API error: 401 Unauthorized at POST https://app.asana.com/api/1.0/tasks'
    )
    expect(calls).toHaveLength(1)
  })

  it('handles missing optional fields gracefully', async () => {
    const { fetch, calls } = fakeFetch((req: RecordedCall) => {
      if (req.url === 'https://app.asana.com/api/1.0/tasks' && req.method === 'POST') {
        return jsonResponse({ data: { gid: '333', name: 'Only Name' } }, 201)
      }
      return jsonResponse({ error: 'not found' }, 404)
    })

    const config: ConnectorConfig = {
      asanaAccessToken: 'token',
      asanaWorkspaceGid: 'ws-1',
      fetch,
    }

    const payload: JotformSubmissionPayload = {
      answers: { first_name: 'Only', last_name: 'Name' },
      submissionID: 'sub-3',
      formID: 'form-3',
    }

    const result = await handle(payload, config)
    expect(result.taskName).toBe('Only Name')

    const sentBody = calls[0].json as { data: { notes: string } }
    expect(sentBody.data.notes).toBe('')
  })

  it('uses injected fetch from config', async () => {
    let captured = false
    const customFetch: typeof fetch = vi.fn(async (_input: string | URL | Request, _init?: RequestInit) => {
      captured = true
      return jsonResponse({ data: { gid: '444', name: 'Custom Fetch' } }, 201)
    })

    const config: ConnectorConfig = {
      asanaAccessToken: 'token',
      asanaWorkspaceGid: 'ws-1',
      fetch: customFetch,
    }

    const payload: JotformSubmissionPayload = {
      answers: { first_name: 'Custom' },
      submissionID: 'sub-4',
      formID: 'form-4',
    }

    await handle(payload, config)
    expect(captured).toBe(true)
    expect(customFetch).toHaveBeenCalledTimes(1)
  })
})

